INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('0486e64a-84fb-430e-9709-7f71c8f8a35d', '21feff02-016d-46e2-bb9d-c27495133b1b', '70. óra: Feladatok megoldása', 'Hétköznapi recept, ötvözet, keverék és arányos osztási feladatok.', 'Matematika', '6. osztály', 'Arány, százalék, szöveges feladatok', '[{"id": "4efc7ab5-1200-44cf-a08b-99623af3d471", "text": "Egy habarcs készítéséhez homok és mész kell 4 : 1 arányban. Hány kg homok kell 50 kg habarcshoz?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "40"}, {"id": "99796963-c903-44e1-917e-81db8e7ec51b", "text": "Egy szörp elkészítéséhez szörp és víz kell 1 : 4 arányban. Hány dl szörp kell 10 dl (1 liter) italhoz?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2"}, {"id": "b3257414-8fe7-4411-918b-a291038009e9", "text": "Ha két testvér 3 : 5 arányban osztozik 800 Ft-on, a nagyobbik rész 500 Ft.", "type": "true-false", "options": [{"id": "cfcd5367-b8dc-46c1-9f0e-8cf4b272fd70", "text": "Igaz (800 / 8 = 100, 5 * 100 = 500)", "isCorrect": true}, {"id": "67df2cc4-1754-4e37-b00a-6809058a4d16", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "73d261bf-8005-44b7-8e83-437f335df025", "text": "Egy téglalap két szomszédos oldalának aránya 2 : 3. Ha a rövidebb oldal 6 cm, hány cm a hosszabb oldal?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "9"}, {"id": "05ac7942-293d-4226-8de5-0000e350ea99", "text": "Melyik állítás igaz az arányos osztásra?", "type": "multiple-choice", "options": [{"id": "19035611-8363-42d9-a76c-a68180e7e82c", "text": "A kapott részek aránya megegyezik a megadott aránnyal", "isCorrect": true}, {"id": "1fd4361f-f9c0-4f7f-a5a6-4c14de591db1", "text": "Minden rész egyenlő nagyságú", "isCorrect": false}, {"id": "371bb75d-05cd-4e19-9bb3-3ce3673387a2", "text": "A részek összege kisebb az eredeti mennyiségnél", "isCorrect": false}, {"id": "1c134c1c-2144-4f3f-84a7-fd21a7518f40", "text": "Nem lehet kiszámolni", "isCorrect": false}], "timeLimit": 15}, {"id": "3bbba23b-65fc-4450-ae18-07f02e59ffcf", "text": "Hány g mész kell 50 kg (4:1 arányú) habarcshoz?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10"}, {"id": "937568f6-48fd-43d7-abab-351e67fc24c7", "text": "A receptekben megadott hozzávalók aránya lehetővé teszi tetszőleges adag elkészítését.", "type": "true-false", "options": [{"id": "1abc74e8-6f23-4bb6-8f3c-864609c2dc2d", "text": "Igaz", "isCorrect": true}, {"id": "efcad4f8-890a-4ccb-844d-c9aefdef3075", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('8d231ea7-597c-446b-99eb-4b0eccdcce80', '21feff02-016d-46e2-bb9d-c27495133b1b', '71. óra: Egyenes arányosság', 'Egyenes arányosság tulajdonságai: hányados állandó, megkétszereződés esetén a másik is megkétszereződik.', 'Matematika', '6. osztály', 'Arány, százalék, szöveges feladatok', '[{"id": "26eec9b0-9449-46d4-8b50-f991789dcdb6", "text": "Mit jelent az egyenes arányosság?", "type": "multiple-choice", "options": [{"id": "d325341a-2052-46e6-90ca-765d7d84b837", "text": "Ha az egyik mennyiség hányszorosára változik, a másik mennyiség is ugyanannyiszorosára változik", "isCorrect": true}, {"id": "3cf6b19d-018f-40be-9273-f5657827792c", "text": "Ha az egyik nő, a másik felére csökken", "isCorrect": false}, {"id": "9ec0d760-db65-4857-8389-d16f507c43d3", "text": "Ha a két mennyiség összege 100", "isCorrect": false}, {"id": "7d2f9efc-95b5-4d89-bb06-85f6e2631b7d", "text": "Ha a két mennyiség szorzata állandó", "isCorrect": false}], "timeLimit": 15}, {"id": "7345e0e4-3dba-40d6-ba5d-e871b830c264", "text": "Egyenes arányosság esetén a két összetartozó érték hányadosa állandó.", "type": "true-false", "options": [{"id": "8135971a-516b-4653-96d0-053e94dd0658", "text": "Igaz", "isCorrect": true}, {"id": "d90288ad-bd07-4fb8-a705-89ba0855ed15", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "35ffc345-3ebf-4722-aaaa-ad5f1dd6633b", "text": "Ha 2 kg alma 800 Ft, mennyibe kerül 6 kg alma? (800 * 3)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2400"}, {"id": "26057c48-859a-4444-87b7-4b0d6f5c06bc", "text": "Ha 3 füzet 600 Ft, mennyibe kerül 1 füzet?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "200"}, {"id": "54334607-be4f-4cc3-a657-a759d249ab10", "text": "Melyik pár között van egyenes arányosság?", "type": "multiple-choice", "options": [{"id": "6c8c8d17-afed-4d3a-9fcd-69a799fe1d8e", "text": "Az azonos árú termék tömege és a fizetendő összeg", "isCorrect": true}, {"id": "2504baa8-415f-4f3a-abda-a4147ce08060", "text": "Az ember életkora és a magassága felnőttként", "isCorrect": false}, {"id": "0c835593-ffa2-4f3a-af48-2cc5a8aecbd9", "text": "A téglalap két oldala rögzített területnél", "isCorrect": false}, {"id": "6c8e8dd5-052d-4bed-aad2-782415cda30c", "text": "A sebesség és az idő adott úton", "isCorrect": false}], "timeLimit": 15}, {"id": "589cfab8-38fd-494d-bc04-7a9c9b0328c1", "text": "Ha a megvásárolt mennyiséget felére csökkentjük, a fizetendő ár is a felére csökken.", "type": "true-false", "options": [{"id": "38161f79-7f4d-4f34-88bb-cc37892f01bc", "text": "Igaz", "isCorrect": true}, {"id": "39c0f42f-60fa-4724-9091-7b95c410cfae", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "ffddc6ad-2e49-4208-ab0c-8917030aef34", "text": "Ha 5 l üdítő 2000 Ft, mennyi 10 l üdítő ára? (Ft-ban)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4000"}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('9ea2163a-8e90-4e1d-9425-0a7c91afdc34', '21feff02-016d-46e2-bb9d-c27495133b1b', '72. óra: Egyenes arányosság grafikonja', 'Az egyenes arányosság ábrázolása a derékszögű koordináta-rendszerben.', 'Matematika', '6. osztály', 'Arány, százalék, szöveges feladatok', '[{"id": "c5b1ed1b-a563-4b9a-a20a-4ac014df89d7", "text": "Milyen alakzat az egyenes arányosság grafikonja a koordináta-rendszerben?", "type": "multiple-choice", "options": [{"id": "794f7a19-3b22-4e3a-9438-d4cbfdfc8a9f", "text": "Az origóból (0; 0) induló félegyenes (vagy egyenes)", "isCorrect": true}, {"id": "d79e7e95-0765-443e-a167-fb76b8f1bc86", "text": "Parabola", "isCorrect": false}, {"id": "6e25c0c8-3b1f-42d5-966a-c031b29c4427", "text": "Körvonal", "isCorrect": false}, {"id": "7923cd67-aab2-467d-afc3-06a64aedf6fb", "text": "Vízszintes egyenes", "isCorrect": false}], "timeLimit": 15}, {"id": "2967f64f-23ef-4916-bdc7-a3406e406560", "text": "Áthalad-e az egyenes arányosság grafikonja az origón (0; 0)?", "type": "true-false", "options": [{"id": "c0b00916-c172-4c84-be42-c7e5fab38d28", "text": "Igaz (0 mennyiség ára 0 Ft)", "isCorrect": true}, {"id": "1e18d305-1900-4965-9fbd-5e323215cbed", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "6d83ede4-ecc7-4b2e-9bac-0458be6f2f6c", "text": "Ha a grafikon áthalad a (1; 300) ponton, mennyi az egységérték?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "300"}, {"id": "3de0e932-3567-4a1e-998d-bd6ee3b58d56", "text": "Ha a grafikon áthalad a (1; 300) ponton, hol metszi a 4-es értéket az y tengelyen? (4 * 300)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1200"}, {"id": "af6b0162-646a-49d3-af26-3a2fd98ee147", "text": "A grafikonról leolvashatók az összetartozó értékpárok.", "type": "true-false", "options": [{"id": "5ce8ddd5-2116-4089-b81b-c03932793059", "text": "Igaz", "isCorrect": true}, {"id": "d72755ce-00bb-4cba-86d9-a192ff1e22a1", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "820369ca-cc2e-4109-ba4d-f777ba9a119b", "text": "Egyenes arányosságnál a meredekség megadja az egységárat.", "type": "true-false", "options": [{"id": "768d970b-720f-413f-87b9-f5b7b0771831", "text": "Igaz", "isCorrect": true}, {"id": "24176183-aa09-4dc5-b0aa-c60c5a00aaeb", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "8fe2853b-e9b7-406d-8378-3d38cbc8aae7", "text": "Ha 0 kg áru 0 Ft, a grafikon a (0;0) pontból indul.", "type": "true-false", "options": [{"id": "7b8c6333-e8ed-4a66-af34-8a5d65b6acea", "text": "Igaz", "isCorrect": true}, {"id": "a909affc-e816-411b-9d2c-a6f26d67c988", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('bdf11f0e-8088-4dcb-a109-1e4f2b28261c', '21feff02-016d-46e2-bb9d-c27495133b1b', '73. óra: Gyakorlóóra', 'Gyakorlati feladatok egyenes arányosságra, táblázatkitöltés, grafikon leolvasás.', 'Matematika', '6. osztály', 'Arány, százalék, szöveges feladatok', '[{"id": "d6784e86-c045-4d97-8aab-e424ebe4d5ee", "text": "Ha 4 méter szalag 1000 Ft, mennyibe kerül 7 méter szalag? (1000/4 = 250 Ft/m, 250*7)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1750"}, {"id": "95fb5147-f7e3-4e0b-a3ab-fc82e4642f7d", "text": "Egy autó 100 km-en 7 liter benzint fogyaszt. Hány litert fogyaszt 400 km-en?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "28"}, {"id": "4d2b593d-fbc5-4730-85e5-0b4e4be5eab5", "text": "Ha 2 óra alatt 120 km-t tesz meg a vonat állandó sebességgel, hány km-t tesz meg 5 óra alatt?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "300"}, {"id": "a7b4dfe5-71f4-48ee-8adc-7b6c6fdb1c2e", "text": "Az egységár meghatározása megkönnyíti a tetszőleges mennyiség árának kiszámítását.", "type": "true-false", "options": [{"id": "26508728-ed29-40f3-ae83-08d4ca643f68", "text": "Igaz", "isCorrect": true}, {"id": "e7c801a0-a301-44f9-8bbd-56527b1c24f4", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "5ca7bb5a-8b9a-4d16-af5e-533d6ac2bd87", "text": "Ha 10 füzet 2500 Ft, mennyibe kerül 4 füzet?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1000"}, {"id": "63bad138-1e3b-4b8b-b258-f57768e33aae", "text": "Egyenes arányosságnál ha a független változót megháromszorozzuk, a függő változó is megháromszorozódik.", "type": "true-false", "options": [{"id": "2cb281f4-8ff2-425e-82c9-b3e118d6c568", "text": "Igaz", "isCorrect": true}, {"id": "e8fd11b2-d511-4f7e-81ec-a67712be5b69", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "6e516af6-620d-425e-870f-69115f9c0020", "text": "Ha 1 kg sajt 4000 Ft, mennyibe kerül 0,25 kg sajt?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1000"}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('86da74d2-aa47-4d6e-9472-2eeb82639077', '21feff02-016d-46e2-bb9d-c27495133b1b', '74. óra: Matematikai játékok', 'Sorozatok szabályai, játékos arányossági feladatok, csoportszervezés.', 'Matematika', '6. osztály', 'Arány, százalék, szöveges feladatok', '[{"id": "def84c37-b706-4884-99a5-ac1b934f0956", "text": "Mi a hiányzó szám a sorozatban: 2, 5, 8, 11, __?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "14"}, {"id": "3955821e-24f3-475b-a122-8c73f311340f", "text": "Mi a szabálya a 2, 4, 8, 16, 32 sorozatnak?", "type": "multiple-choice", "options": [{"id": "1f8170c4-606a-4f63-8578-7892c12c3a93", "text": "Szorzás 2-vel (*2)", "isCorrect": true}, {"id": "ffe17c51-3095-4255-bb9e-44320c44ea29", "text": "Hozzáadás 2-vel (+2)", "isCorrect": false}, {"id": "3641e5e3-e1ce-479f-bb29-600ce6f9c31d", "text": "Négyzetre emelés", "isCorrect": false}, {"id": "038c80ff-22f4-4efa-875f-93abe50a7ec2", "text": "Kivonás 2-vel", "isCorrect": false}], "timeLimit": 15}, {"id": "f9e4d1b3-db5a-4d99-9ba3-d4e7dc80cb10", "text": "A sorozatszabály megállapításához több egymást követő elem vizsgálata szükséges.", "type": "true-false", "options": [{"id": "beafe447-fc9b-4e15-b913-8f0a5be693f7", "text": "Igaz", "isCorrect": true}, {"id": "731c6369-ca19-401f-ac9b-7202b17c98c5", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "700adbfc-4af9-4fc1-83cc-980ff60a124e", "text": "Mi a következő szám a 100, 90, 80, 70 sorozatban?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "60"}, {"id": "b7135605-adac-4ef4-be75-846139827cae", "text": "Mi a hiányzó szám a Fibonacci sorozatban: 1, 1, 2, 3, 5, 8, __?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "13"}, {"id": "c85d21b3-7485-4bbd-8313-d98b3043b06b", "text": "A növekvő számsorozatban az elemek értéke folyamatosan nő.", "type": "true-false", "options": [{"id": "b3c258e8-7877-42bd-8a94-3e822953b2a3", "text": "Igaz", "isCorrect": true}, {"id": "adc63050-d3c9-4b51-bd78-7e2010a1d163", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "5279c515-33e0-4e86-8c7a-8bebd5f76a3d", "text": "Mi a szabálya a 3, 9, 27, 81 sorozatnak?", "type": "multiple-choice", "options": [{"id": "73d5cfc7-b0d2-4cac-bea8-76d2366009cb", "text": "Szorzás 3-mal (*3)", "isCorrect": true}, {"id": "32d9c164-e60a-497f-8711-93df43126935", "text": "Hozzáadás 6-tal", "isCorrect": false}, {"id": "ef9577ed-d64d-4074-ab5d-ce58744f1e1f", "text": "Hozzáadás 3-mal", "isCorrect": false}, {"id": "1d71a126-82fd-4290-ba42-8be49fc24f63", "text": "Osztás 3-mal", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('afb2d53e-4d19-40bb-aaee-55db6e1313db', '21feff02-016d-46e2-bb9d-c27495133b1b', '75. óra: Szabályok, megfeleltetések', 'Sorozatok megadása képlettel, alakzat-sorozatok, szabályfelismerés.', 'Matematika', '6. osztály', 'Arány, százalék, szöveges feladatok', '[{"id": "16b505aa-86f2-4fb8-b768-4aae1360372b", "text": "Ha a sorozat nth elemének szabálya: a_n = 3 * n, mennyi a 4. elem?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "12"}, {"id": "b7733847-bd4a-4161-9324-7e14faa6211b", "text": "Ha a sorozat szabálya: a_n = 2 * n + 1, mennyi a 5. elem? (2*5 + 1)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "11"}, {"id": "29866836-b59b-4387-b7d1-993e59ba89eb", "text": "A számsorozatok a mindennapi mérésekben és a természetben is megjelennek.", "type": "true-false", "options": [{"id": "bf893f40-3ded-45b2-a4d7-d21db18a0340", "text": "Igaz", "isCorrect": true}, {"id": "7c6f5578-41b0-43e5-a188-3fbe475edca9", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "a33d3f17-9bf5-4386-8dac-474873300161", "text": "Ha a sorozat szabálya a_n = n * n (négyzetszámok), mennyi a 4. elem?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "16"}, {"id": "d9336024-b8a3-4ba5-aa9f-25d140e07091", "text": "Melyik sorozat szabálya a ''Hozzáadás 5-tel''?", "type": "multiple-choice", "options": [{"id": "bb22ff58-57e3-487c-9229-cd962d473817", "text": "5, 10, 15, 20, 25", "isCorrect": true}, {"id": "9fb361d0-a45d-4329-9d7a-c7d20dff7a94", "text": "5, 25, 125", "isCorrect": false}, {"id": "7399167d-7aa1-492e-82fd-f7277590dc22", "text": "5, 4, 3, 2", "isCorrect": false}, {"id": "85f79ed9-4aef-4867-95db-dd8c01b8055d", "text": "1, 2, 4, 8", "isCorrect": false}], "timeLimit": 15}, {"id": "b4909876-32e7-41ed-84aa-3a4d514bcd28", "text": "Az alakzat-sorozatoknál az elemek száma (pl. gyufaszálak száma) számsorozatot alkot.", "type": "true-false", "options": [{"id": "2a71cad1-cf89-467c-9570-443b4370d585", "text": "Igaz", "isCorrect": true}, {"id": "be44c897-b1af-4ad5-8ca9-1a380b2fd554", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "c40050a9-6969-4378-89ae-6781faf4c3fb", "text": "Mennyi a 10. páros természetes szám (2, 4, 6, ...)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "20"}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('0845b778-db92-4184-9859-dee5415cf535', '21feff02-016d-46e2-bb9d-c27495133b1b', '76. óra: Gyakorlóóra', 'Gyakorló feladatok sorozatok szabályaira és egyenes arányosságra.', 'Matematika', '6. osztály', 'Arány, százalék, szöveges feladatok', '[{"id": "0c00a668-3563-42a8-ab2f-53698e6ad415", "text": "Mi a hiányzó szám a sorozatban: 1, 4, 9, 16, __, 36? (négyzetszámok)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "25"}, {"id": "fd4c927c-179d-4f1d-a09d-2deae45b2fa9", "text": "Mi a hiányzó szám: 50, 43, 36, 29, __? (kivonás 7-tel)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "22"}, {"id": "8d3b485f-0be3-4eb3-9cd9-dc010f326b40", "text": "Ha 3 kg narancs 1500 Ft, mennyi 1 kg narancs ára?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "500"}, {"id": "e5587a90-1888-46f6-b47e-3711f58a7217", "text": "Ha 1 kg narancs 500 Ft, mennyibe kerül 8 kg narancs?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4000"}, {"id": "5ddcd771-7689-4b34-83ea-942fe0557386", "text": "Egy sorozatnak több különböző folytatása is elképzelhető, ha nem rögzítjük pontosan a szabályt.", "type": "true-false", "options": [{"id": "6c7d5a38-dfe6-4724-adde-91c8ed4bd6d0", "text": "Igaz", "isCorrect": true}, {"id": "0a5e8a2d-bd92-4cd5-bf45-d017caa6c3e9", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "609614db-ba57-4b34-8593-ac58bf948a3d", "text": "Mi a szabálya a 1, 3, 7, 15, 31 sorozatnak?", "type": "multiple-choice", "options": [{"id": "a08491de-ce61-4950-abd3-9040ec929d75", "text": "Szorzás 2-vel és hozzáadás 1-gyel (*2 + 1)", "isCorrect": true}, {"id": "1262010d-9be1-4e84-a031-fd006491fa21", "text": "Hozzáadás 2-vel", "isCorrect": false}, {"id": "f84d6ea8-b1f5-4528-9b73-ea98d3b69f58", "text": "Szorzás 3-mal", "isCorrect": false}, {"id": "a5b9dc2c-b2b2-4a0f-8c08-7fbab21ac7d6", "text": "Négyzetre emelés", "isCorrect": false}], "timeLimit": 15}, {"id": "c21c44ec-d91d-407a-adab-1f5c6937c57d", "text": "A számsorozatok logikus gondolkodásra nevelnek.", "type": "true-false", "options": [{"id": "ed7d464b-3c2f-4e0d-8e1e-b6b44e456a2e", "text": "Igaz", "isCorrect": true}, {"id": "d5244f0b-9000-4236-af1d-09af8a404906", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('b32a7120-29bc-4090-8757-5e47d6784eff', '21feff02-016d-46e2-bb9d-c27495133b1b', '77. óra: Törtrész', 'Törtrész kiszámítása és kapcsolata az egyenes arányossággal.', 'Matematika', '6. osztály', 'Arány, százalék, szöveges feladatok', '[{"id": "197280d9-95d0-4180-b6c2-8f19f59119d8", "text": "Hogyan számítjuk ki egy mennyiség 3/5 részét?", "type": "multiple-choice", "options": [{"id": "a7ee483d-c53d-4e48-805a-7baac677fb80", "text": "Elosztjuk 5-tel és megszorozzuk 3-mal (vagy megszorozzuk 3/5-tel)", "isCorrect": true}, {"id": "303b5b86-17b3-41d8-be6e-7a8d6671da60", "text": "Megszorozzuk 5-tel és elosztjuk 3-mal", "isCorrect": false}, {"id": "075d1be0-d15c-4070-84e8-e1f39013dec8", "text": "Hozzáadunk 3/5-öt", "isCorrect": false}, {"id": "d49661ca-464e-4c9f-a9cb-d8062c8fe0d8", "text": "Kivonunk 3/5-öt", "isCorrect": false}], "timeLimit": 15}, {"id": "6f46473b-0c11-4f9a-a8d9-fbe08371291b", "text": "Mennyi 80-nak a 3/4 része?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "60"}, {"id": "df2110f5-8b63-4f4d-bfdb-e9c6fcbe5688", "text": "Mennyi 150-nek a 2/3 része?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "100"}, {"id": "e64df3f9-5e0b-43e4-aa2f-086ca38bdcdf", "text": "A törtrész kiszámítása egyenesen arányos a megadott tört nagyságával.", "type": "true-false", "options": [{"id": "31186ac6-06dc-4afb-94b5-e49b7c36a030", "text": "Igaz", "isCorrect": true}, {"id": "631bad33-3600-4b7e-89d9-8690845a9c3a", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "af914fa8-1375-46a5-ab7c-610bd888f0ac", "text": "Mennyi 200-nak az 1/10 része?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "20"}, {"id": "52ca3c7b-2335-4436-9c83-50bacdd48c7b", "text": "Ha egy mennyiség 1/2 része 30, mennyi a teljes mennyiség? (30 * 2)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "60"}, {"id": "05e6b18c-b89f-4ba9-a09f-a21598bbf44d", "text": "Mennyi 90-nek a 4/9 része?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "40"}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('00e7c1d9-e01e-42b8-a409-b7978e061ff0', '21feff02-016d-46e2-bb9d-c27495133b1b', '78. óra: Feladatmegoldás', 'Összetett feladatok megoldása törtrész kiszámításával.', 'Matematika', '6. osztály', 'Arány, százalék, szöveges feladatok', '[{"id": "0bcc46eb-f265-4976-a77d-80ce36db7180", "text": "Egy 600 oldalú könyvnek elolvastuk a 3/5 részét. Hány oldalt olvastunk el?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "360"}, {"id": "629a6719-25bf-402d-bcf3-05be56951f30", "text": "Egy 600 oldalú könyvnek elolvastuk a 3/5 részét. Hány oldal van még hátra? (600 - 360)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "240"}, {"id": "66198ef7-4b8f-47e0-9248-c901930d76de", "text": "Kati zsebpénze 4000 Ft. Elköltötte a 3/8 részét. Hány Ft-ot költött el? (4000 * 3/8)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1500"}, {"id": "ccd3d3f1-4ee4-4ffb-939d-6fd46df40dfb", "text": "Kati zsebpénze 4000 Ft. Elköltötte a 3/8 részét. Hány Ft-ja maradt?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2500"}, {"id": "ff6ce4e8-a8f2-42ef-ad27-43b5b3c7c713", "text": "Ha a törtrész kiszámítása után a maradékot keresük, a teljesből kivonjuk a törtrészt.", "type": "true-false", "options": [{"id": "d78550ea-a188-4bad-9de7-60db329d9657", "text": "Igaz", "isCorrect": true}, {"id": "18e89470-a4d5-4dc7-84ab-2fed37366a23", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "d4b621bb-1f9c-4167-b963-52249cecd803", "text": "Mennyi 120-nak a 5/6 része?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "100"}, {"id": "658b9be8-28f8-4ef1-8a9a-bb36200f3f89", "text": "A törtrész kiszámítása fontos a pénzügyi és mindennapi döntésekben.", "type": "true-false", "options": [{"id": "d99bc91f-4dd8-409e-8940-b0764d2beb54", "text": "Igaz", "isCorrect": true}, {"id": "e4431db0-6a8a-4972-9c18-fe0d8654573f", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('5203d46a-f7ad-4c73-9cfb-b2b2af21f0ca', '21feff02-016d-46e2-bb9d-c27495133b1b', '79. óra: Számonkérés', 'Számonkérés az arány, egyenes arányosság és törtrész témakörökből (10 kérdés).', 'Matematika', '6. osztály', 'Arány, százalék, szöveges feladatok', '[{"id": "9c6bd67e-4919-4a3e-8ea7-0816b62fe4b8", "text": "1. Mennyi a 6 : 18 arány egyszerűsített alakja?", "type": "multiple-choice", "options": [{"id": "c3e53dc0-14a7-4b19-8577-dabfbf6321a7", "text": "1 : 3", "isCorrect": true}, {"id": "ecec8ea4-3102-407e-8336-b29f72b570dd", "text": "1 : 2", "isCorrect": false}, {"id": "67cd1118-1b1c-4516-94fc-1787f0ea3ff9", "text": "3 : 1", "isCorrect": false}, {"id": "31c09ec0-f092-4c34-a629-40f2ff5c8523", "text": "2 : 3", "isCorrect": false}], "timeLimit": 15}, {"id": "3844854d-7d4e-46f8-b7f3-071d596692b2", "text": "2. Ossz el 400 Ft-ot 1 : 3 arányban! Hány Ft a kisebbik rész?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "100"}, {"id": "26eb92e3-9b82-48d1-8110-5cfb0b00a320", "text": "3. Ossz el 400 Ft-ot 1 : 3 arányban! Hány Ft a nagyobbik rész?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "300"}, {"id": "f2ad6bb6-a333-461f-8758-987767e06af7", "text": "4. Ha 3 kg alma 900 Ft, mennyibe kerül 5 kg alma?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1500"}, {"id": "05e7c5af-5f6f-4114-b335-5f085aac5259", "text": "5. Mennyi 120-nak a 3/4 része?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "90"}, {"id": "d86d45ab-4655-4732-9384-ee1a618388e7", "text": "6. Az egyenes arányosság grafikonja az origóból induló félegyenes.", "type": "true-false", "options": [{"id": "64aa3b35-4b28-4e82-b7af-625495a20ce8", "text": "Igaz", "isCorrect": true}, {"id": "17cff6f7-8c0b-402c-99f1-570248dcbceb", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "be8506a4-1341-4721-9006-c62dea3c7e43", "text": "7. Mi a hiányzó szám a sorozatban: 4, 8, 12, 16, __?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "20"}, {"id": "7b24e3f0-1f6a-40e2-9cf1-6ac05aeada36", "text": "8. Ha egy mennyiség 1/3-a 15, mennyi az egész mennyiség?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "45"}, {"id": "c4dcf139-3d2e-4760-982c-16f8aa0f7116", "text": "9. Két mennyiség aránya hányados formájában is felírható.", "type": "true-false", "options": [{"id": "324e95b1-6327-4871-9ed2-0df64c84ec33", "text": "Igaz", "isCorrect": true}, {"id": "6efb8499-2036-4b32-9132-84fbaf094a98", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "cedbae84-ee44-4862-a201-2c496ca6bc04", "text": "10. Mennyi 50-nek a 4/5 része?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "40"}]'::jsonb, true, NOW());